	--radius-2xl: calc(var(--radius) + 8px);
	--radius-3xl: calc(var(--radius) + 12px);
	--radius-4xl: calc(var(--radius) + 16px);
}

.mesh-gradient {
	background-color: #ffffff;
	background-image:
		radial-gradient(at 0% 0%, hsl(var(--primary) / 0.05) 0, transparent 50%),
		radial-gradient(at 100% 0%, hsl(var(--primary) / 0.05) 0, transparent 50%),
		radial-gradient(at 100% 100%, hsl(var(--primary) / 0.08) 0, transparent 50%),
		radial-gradient(at 0% 100%, hsl(var(--primary) / 0.04) 0, transparent 50%);
}

.text-gradient {
	background: linear-gradient(
		to right,
		hsl(var(--primary)),
		hsl(var(--primary) / 0.8)
	);
	-webkit-background-clip: text;
	background-clip: text;
	color: transparent;
}

.bg-gradient-primary {
	background: linear-gradient(
		to right,
		hsl(var(--primary)),
		hsl(var(--primary) / 0.9)
	);
}

.stroke-primary {
	stroke: hsl(var(--primary));
}

.fill-primary {
	fill: hsl(var(--primary));
}

@layer base {
	* {
		@apply border-border outline-ring/50;
	}
	body {
		@apply font-sans bg-background text-foreground;
	}
	html {
		@apply font-sans;
	}
}

