    22→interface Org {
    23→	id: string;
    24→	name: string;
    25→	slug: string;
    26→}
    27→
    28→export default function OrganizationSwitcher() {
    29→	const router = useRouter();
    30→	const { data: session, isPending: isSessionPending } =
    31→		authClient.useSession();
    32→	const [organizations, setOrganizations] = useState<Org[]>([]);
    33→	const [isOrgsPending, setIsOrgsPending] = useState(true);
    34→
    35→	useEffect(() => {
    36→		async function fetchOrganizations() {
    37→			try {
    38→				const result = await authClient.organization.list();
    39→				if (result.data) {
    40→					setOrganizations(result.data);
    41→				}
    42→			} catch (error) {
    43→				console.error("Failed to fetch organizations:", error);
    44→			} finally {
    45→				setIsOrgsPending(false);
    46→			}
    47→		}
    48→
    49→		if (session?.user) {
    50→			fetchOrganizations();
    51→		}
    52→	}, [session?.user]);
    53→
    54→	const isPending = isSessionPending || isOrgsPending;
    55→
    56→	if (isPending) {
    57→		return <Skeleton className="h-9 w-40" />;
    58→	}
    59→
    60→	if (!session || !organizations || organizations.length === 0) {
    61→		return null;
    62→	}
    63→
    64→	const currentOrg = organizations.find(
    65→		(org: Org) => org.id === session.session.activeOrganizationId,
    66→	);
    67→
    68→	const handleSwitchOrganization = async (organizationId: string) => {
    69→		try {
    70→			const result = await authClient.organization.setActive({
    71→				organizationId,
    72→			});
    73→
    74→			if (result.error) {
    75→				toast.error(result.error.message || "Failed to switch organization");
    76→				return;
    77→			}
    78→
