     1→"use client";
     2→
     3→import {
     4→	DndContext,
     5→	DragOverlay,
     6→	defaultDropAnimation,
     7→	KeyboardSensor,
     8→	PointerSensor,
     9→	useSensor,
    10→	useSensors,
    11→} from "@dnd-kit/core";
    12→import { sortableKeyboardCoordinates } from "@dnd-kit/sortable";
    13→import type { Question, Survey } from "@orksys-survey/db";
    14→import { PanelLeftClose, PanelRightClose } from "lucide-react";
    15→import { useEffect, useState } from "react";
    16→
    17→import { Button } from "@/components/ui/button";
    18→import { Sheet, SheetContent } from "@/components/ui/sheet";
    19→import { useMediaQuery } from "@/hooks/use-media-query";
    20→import { cn } from "@/lib/utils";
    21→
    22→import { BuilderCanvas } from "./builder-canvas";
    23→import { BuilderHeader } from "./builder-header";
    24→import { SurveyBuilderProvider } from "./context";
    25→import { DragOverlayRenderer } from "./drag-overlay-renderer";
    26→import { useDragHandlers } from "./hooks/use-drag-handlers";
    27→import { useQuestionMutations } from "./hooks/use-question-mutations";
    28→import { PropertiesPanel } from "./properties-panel";
    29→import { QuestionPalette } from "./question-palette";
    30→
    31→interface SurveyBuilderProps {
    32→	survey: Survey;
    33→	questions: Question[];
    34→	className?: string;
    35→}
    36→
    37→export function SurveyBuilder({
    38→	survey,
    39→	questions: initialQuestions,
    40→	className,
    41→}: SurveyBuilderProps) {
    42→	const [selectedQuestionId, setSelectedQuestionId] = useState<string | null>(
    43→		null,
    44→	);
    45→	const [activeTab, setActiveTab] = useState<"build" | "preview" | "share">(
    46→		"build",
    47→	);
    48→	const [questions, setQuestions] = useState(initialQuestions);
    49→	const [paletteOpen, setPaletteOpen] = useState(false);
    50→	const [propertiesOpen, setPropertiesOpen] = useState(false);
    51→	const [settingsOpen, setSettingsOpen] = useState(false);
    52→
    53→	// Responsive breakpoints
    54→	const isDesktop = useMediaQuery("(min-width: 1024px)");
    55→
    56→	// Sync state when initialQuestions changes
    57→	useEffect(() => {
    58→		setQuestions(initialQuestions);
    59→	}, [initialQuestions]);
    60→
    61→	// Get mutations
    62→	const { reorderMutation } = useQuestionMutations({
    63→		survey,
    64→		onQuestionCreated: (newQuestion) => {
    65→			// Replace optimistic question with real one
    66→			setQuestions((currentQuestions) => {
    67→				const tempId = selectedQuestionId?.startsWith("temp-")
    68→					? selectedQuestionId
    69→					: null;
    70→				if (!tempId) return currentQuestions;
    71→
    72→				return currentQuestions.map((q) => (q.id === tempId ? newQuestion : q));
    73→			});
    74→
    75→			setSelectedQuestionId((currentId) => {
    76→				const tempId = currentId?.startsWith("temp-") ? currentId : null;
    77→				return tempId ? newQuestion.id : currentId;
    78→			});
    79→		},
    80→		onQuestionCreateError: () => {
    81→			// Revert on error
    82→			if (selectedQuestionId?.startsWith("temp-")) {
    83→				setSelectedQuestionId(null);
    84→			}
    85→		},
    86→	});
    87→
    88→	// Get drag handlers
    89→	const {
    90→		activeDragItem,
    91→		overId,
    92→		collisionDetection,
    93→		handleDragStart,
    94→		handleDragOver,
    95→		handleDragEnd,
    96→	} = useDragHandlers({
    97→		questions,
    98→		setQuestions,
    99→		survey,
   100→		selectedQuestionId,
   101→		setSelectedQuestionId,
   102→		reorderMutation,
   103→	});
   104→
   105→	// DnD sensors
   106→	const sensors = useSensors(
   107→		useSensor(PointerSensor, {
   108→			activationConstraint: {
   109→				distance: 5,
   110→			},
   111→		}),
   112→		useSensor(KeyboardSensor, {
   113→			coordinateGetter: sortableKeyboardCoordinates,
   114→		}),
   115→	);
   116→
   117→	const safeQuestions = questions || [];
   118→
   119→	return (
   120→		<SurveyBuilderProvider
   121→			survey={survey}
   122→			questions={questions}
   123→			selectedQuestionId={selectedQuestionId}
   124→			setSelectedQuestionId={setSelectedQuestionId}
   125→			activeTab={activeTab}
   126→			setActiveTab={setActiveTab}
   127→			onQuestionsChange={setQuestions}
   128→			paletteOpen={paletteOpen}
   129→			setPaletteOpen={setPaletteOpen}
   130→			propertiesOpen={propertiesOpen}
   131→			setPropertiesOpen={setPropertiesOpen}
   132→			settingsOpen={settingsOpen}
   133→			setSettingsOpen={setSettingsOpen}
   134→		>
   135→			<DndContext
   136→				sensors={sensors}
   137→				collisionDetection={collisionDetection}
   138→				onDragStart={handleDragStart}
   139→				onDragOver={handleDragOver}
   140→				onDragEnd={handleDragEnd}
   141→			>
   142→				<div className={cn("flex h-full flex-col", className)}>
   143→					<BuilderHeader
   144→						leftActions={
   145→							!isDesktop &&
   146→							activeTab === "build" && (
   147→								<div className="flex items-center gap-1">
   148→									<Button
   149→										variant="ghost"
   150→										size="icon"
   151→										onClick={() => setPaletteOpen(!paletteOpen)}
   152→									>
   153→										<PanelLeftClose className="h-4 w-4" />
   154→									</Button>
   155→								</div>
   156→							)
   157→						}
   158→						rightActions={
   159→							!isDesktop &&
   160→							activeTab === "build" && (
   161→								<div className="flex items-center gap-1">
   162→									<Button
   163→										variant="ghost"
   164→										size="icon"
   165→										onClick={() => setPropertiesOpen(!propertiesOpen)}
   166→									>
   167→										<PanelRightClose className="h-4 w-4" />
   168→									</Button>
   169→								</div>
   170→							)
   171→						}
   172→					/>
   173→					<div className="flex flex-1 overflow-hidden">
   174→						{/* Left Palette - Responsive */}
   175→						{activeTab === "build" && (
   176→							<>
   177→								{/* Desktop: Fixed sidebar */}
   178→								{isDesktop && <QuestionPalette />}
   179→
   180→								{/* Tablet/Mobile: Sheet overlay */}
   181→								{!isDesktop && (
   182→									<Sheet open={paletteOpen} onOpenChange={setPaletteOpen}>
   183→										<SheetContent side="left" className="w-72 p-0">
   184→											<QuestionPalette />
   185→										</SheetContent>
   186→									</Sheet>
   187→								)}
   188→							</>
   189→						)}
   190→
   191→						{/* Canvas */}
   192→						<BuilderCanvas
   193→							questions={questions}
   194→							onQuestionsChange={setQuestions}
   195→							activeDragItem={activeDragItem}
   196→							overId={overId}
   197→						/>
   198→
   199→						{/* Right Properties Panel - Responsive */}
   200→						{activeTab === "build" && (
   201→							<>
   202→								{/* Desktop: Fixed sidebar */}
   203→								{isDesktop && <PropertiesPanel />}
   204→
   205→								{/* Tablet/Mobile: Sheet overlay */}
   206→								{!isDesktop && (
   207→									<Sheet open={propertiesOpen} onOpenChange={setPropertiesOpen}>
   208→										<SheetContent side="right" className="w-80 p-0">
   209→											<PropertiesPanel />
   210→										</SheetContent>
   211→									</Sheet>
   212→								)}
   213→							</>
   214→						)}
   215→					</div>
   216→				</div>
   217→
   218→				<DragOverlay dropAnimation={defaultDropAnimation}>
   219→					<DragOverlayRenderer
   220→						activeDragItem={activeDragItem}
   221→						questions={safeQuestions}
   222→						selectedQuestionId={selectedQuestionId}
   223→					/>
   224→				</DragOverlay>
   225→			</DndContext>
   226→		</SurveyBuilderProvider>
   227→	);
   228→}
   229→
   230→// Re-export sub-components for compound pattern
   231→export { BuilderCanvas } from "./builder-canvas";
   232→export { BuilderHeader } from "./builder-header";
   233→export type { TabValue } from "./builder-header/builder-tabs";
   234→export { useSurveyBuilder } from "./context";
   235→export { useDragHandlers } from "./hooks/use-drag-handlers";
   236→export { useQuestionMutations } from "./hooks/use-question-mutations";
   237→export { PropertiesPanel } from "./properties-panel";
   238→export { QuestionPalette } from "./question-palette";
   239→// Re-export types and hooks for external use
   240→export type { DragItem, SurveyBuilderContextValue } from "./types";
   241→

