     1→"use client";
     2→
     3→import { Building2, Check, ChevronsUpDown } from "lucide-react";
     4→import { useRouter } from "next/navigation";
     5→import { useEffect, useState } from "react";
     6→import { toast } from "sonner";
     7→
     8→import {
     9→	DropdownMenu,
    10→	DropdownMenuContent,
    11→	DropdownMenuGroup,
    12→	DropdownMenuItem,
    13→	DropdownMenuLabel,
    14→	DropdownMenuSeparator,
    15→	DropdownMenuTrigger,
    16→} from "@/components/ui/dropdown-menu";
    17→import { authClient } from "@/lib/auth-client";
    18→
    19→import { Button } from "./ui/button";
    20→import { Skeleton } from "./ui/skeleton";
    21→
    22→interface Org {
    23→	id: string;
    24→	name: string;
    25→	slug: string;
    26→}
    27→
    28→export default function OrganizationSwitcher() {
    29→	const router = useRouter();
    30→	const { data: session, isPending: isSessionPending } =
    31→		authClient.useSession();
    32→	const [organizations, setOrganizations] = useState<Org[]>([]);
    33→	const [isOrgsPending, setIsOrgsPending] = useState(true);
    34→
    35→	useEffect(() => {
    36→		async function fetchOrganizations() {
    37→			try {
    38→				const result = await authClient.organization.list();
    39→				if (result.data) {
    40→					setOrganizations(result.data);
    41→				}
    42→			} catch (error) {
    43→				console.error("Failed to fetch organizations:", error);
    44→			} finally {
    45→				setIsOrgsPending(false);
    46→			}
    47→		}
    48→
    49→		if (session?.user) {
    50→			fetchOrganizations();
    51→		}
    52→	}, [session?.user]);
