    27→
    28→export default function OrganizationSwitcher() {
    29→	const router = useRouter();
    30→	const { data: session, isPending: isSessionPending } =
    31→		authClient.useSession();
    32→	const [organizations, setOrganizations] = useState<Org[]>([]);
    33→	const [isOrgsPending, setIsOrgsPending] = useState(true);
    34→
    35→	useEffect(() => {
    36→		async function fetchOrganizations() {
    37→			try {
    38→				const result = await authClient.organization.list();
    39→				if (result.data) {
    40→					setOrganizations(result.data);
    41→				}
    42→			} catch (error) {
    43→				console.error("Failed to fetch organizations:", error);
    44→			} finally {
    45→				setIsOrgsPending(false);
    46→			}
    47→		}
    48→
    49→		if (session?.user) {
    50→			fetchOrganizations();
    51→		}
    52→	}, [session?.user]);
    53→
    54→	const isPending = isSessionPending || isOrgsPending;
    55→
    56→	if (isPending) {
    57→		return <Skeleton className="h-9 w-40" />;
    58→	}
    59→
    60→	if (!session || !organizations || organizations.length === 0) {
    61→		return null;
    62→	}
    63→
    64→	const currentOrg = organizations.find(
    65→		(org: Org) => org.id === session.session.activeOrganizationId,
    66→	);
    67→
    68→	const handleSwitchOrganization = async (organizationId: string) => {
    69→		try {
    70→			const result = await authClient.organization.setActive({
    71→				organizationId,
    72→			});
    73→
    74→			if (result.error) {
    75→				toast.error(result.error.message || "Failed to switch organization");
    76→				return;
    77→			}
    78→
    79→			router.refresh();
    80→		} catch (error) {
    81→			toast.error("An unexpected error occurred");
    82→		}
    83→	};
    84→
    85→	return (
    86→		<DropdownMenu>
    87→			<DropdownMenuTrigger
    88→				render={<Button variant="outline" className="gap-2" />}
    89→			>
    90→				<Building2 className="h-4 w-4" />
    91→				<span className="max-w-32 truncate">
    92→					{currentOrg?.name || "Select org"}
    93→				</span>
    94→				<ChevronsUpDown className="h-4 w-4 opacity-50" />
    95→			</DropdownMenuTrigger>
    96→			<DropdownMenuContent className="w-56 bg-card">
    97→				<DropdownMenuGroup>
    98→					<DropdownMenuLabel>Organizations</DropdownMenuLabel>
    99→					<DropdownMenuSeparator />
   100→					{organizations.map((org: Org) => (
   101→						<DropdownMenuItem
   102→							key={org.id}
   103→							onClick={() => handleSwitchOrganization(org.id)}
   104→							className="justify-between"
   105→						>
   106→							<span className="truncate">{org.name}</span>
   107→							{org.id === session.session.activeOrganizationId && (
   108→								<Check className="h-4 w-4" />
   109→							)}
   110→						</DropdownMenuItem>
   111→					))}
   112→				</DropdownMenuGroup>
   113→			</DropdownMenuContent>
   114→		</DropdownMenu>
   115→	);
   116→}
