Now I have enough context. Let me provide a comprehensive implementation plan for the modern, flexible header component.

---

## Modern Header Component Design Plan

Based on my analysis of the codebase, here is a comprehensive implementation plan for a modern, flexible header component for protected pages.

---

### 1. Component Structure and File Organization

I recommend creating a new `app-header` directory with a compound component structure:

```
apps/web/src/components/app-header/
├── index.ts                    # Public exports
├── context.tsx                 # Header context for state sharing
├── app-header.tsx              # Root header component
├── header-logo.tsx             # Logo component
├── header-nav.tsx              # Desktop navigation (NavigationMenu)
├── header-nav-item.tsx         # Individual nav item
├── header-actions.tsx          # Right side actions container
├── mobile-menu.tsx             # Mobile sheet menu
├── mobile-nav-item.tsx         # Mobile navigation link
├── breadcrumb.tsx              # Optional breadcrumb component
└── types.ts                    # Shared types
```

---

### 2. Compound Component API Design

The header should support both a composed API (compound pattern) and a simplified props-based API:

```tsx
// Option 1: Simplified API (recommended for most cases)
<AppHeader
  logo={<Logo />}
  navItems={navItems}
  showOrgSwitcher
  showThemeToggle
  showUserMenu
/>

// Option 2: Compound Component API (for maximum flexibility)
<AppHeader>
  <AppHeader.Logo />
  <AppHeader.Nav>
    <AppHeader.NavItem href="/dashboard">Dashboard</AppHeader.NavItem>
    <AppHeader.NavItem href="/surveys">Surveys</AppHeader.NavItem>
  </AppHeader.Nav>
  <AppHeader.Actions>
    <AppHeader.OrgSwitcher />
    <AppHeader.ThemeToggle />
    <AppHeader.UserMenu />
  </AppHeader.Actions>
  <AppHeader.MobileMenu />
</AppHeader>
```

---

### 3. Core Implementation

#### Types (`types.ts`)

```tsx
import type { ReactNode } from "react";

export interface NavItem {
  href: string;
  label: string;
  icon?: ReactNode;
  badge?: string | number;
  disabled?: boolean;
}

export interface AppHeaderContextValue {
  navItems: NavItem[];
  currentPath: string;
  mobileMenuOpen: boolean;
  setMobileMenuOpen: (open: boolean) => void;
}

export interface AppHeaderProps {
  children?: ReactNode;
  className?: string;
  /** Logo element - defaults to app logo */
  logo?: ReactNode;
  /** Navigation items configuration */
  navItems?: NavItem[];
  /** Show organization switcher */
  showOrgSwitcher?: boolean;
  /** Show theme toggle */
  showThemeToggle?: boolean;
  /** Show user menu */
  showUserMenu?: boolean;
  /** Breadcrumb items for current page */
  breadcrumbs?: Array<{ label: string; href?: string }>;
  /** Sticky header */
  sticky?: boolean;
  /** Border variant */
  border?: "none" | "bottom" | "full";
}
```

#### Context (`context.tsx`)

```tsx
"use client";

import { createContext, use, useState, useMemo } from "react";
import { usePathname } from "next/navigation";
import type { AppHeaderContextValue, NavItem } from "./types";

const AppHeaderContext = createContext<AppHeaderContextValue | null>(null);

const defaultNavItems: NavItem[] = [
  { href: "/dashboard", label: "Dashboard" },
  { href: "/surveys", label: "Surveys" },
  { href: "/todos", label: "Todos" },
];

export function AppHeaderProvider({
  children,
  navItems = defaultNavItems,
}: {
  children: React.ReactNode;
  navItems?: NavItem[];
}) {
  const pathname = usePathname();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const contextValue = useMemo<AppHeaderContextValue>(
    () => ({
      navItems,
      currentPath: pathname,
      mobileMenuOpen,
      setMobileMenuOpen,
    }),
    [navItems, pathname, mobileMenuOpen],
  );

  return (
    <AppHeaderContext.Provider value={contextValue}>
      {children}
    </AppHeaderContext.Provider>
  );
}

export function useAppHeader() {
  const context = use(AppHeaderContext);
  if (!context) {
    throw new Error("useAppHeader must be used within AppHeaderProvider");
  }
  return context;
}
```

#### Root Component (`app-header.tsx`)

```tsx
"use client";

import { Menu } from "lucide-react";
import Link from "next/link";
import type { ReactNode } from "react";

import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { ModeToggle } from "@/components/mode-toggle";
import OrganizationSwitcher from "@/components/organization-switcher";
import UserMenu from "@/components/user-menu";

import { AppHeaderProvider, useAppHeader } from "./context";
import { HeaderNav } from "./header-nav";
import { MobileMenu } from "./mobile-menu";
import { Breadcrumb } from "./breadcrumb";
import type { AppHeaderProps, NavItem } from "./types";

// Default Logo Component
function DefaultLogo() {
  return (
    <Link
      href="/dashboard"
      className="flex items-center gap-2 font-semibold text-foreground"
    >
      <span className="text-lg">Handshake</span>
    </Link>
  );
}

// Internal header content (uses context)
function AppHeaderContent({
  logo,
  showOrgSwitcher = true,
  showThemeToggle = true,
  showUserMenu = true,
  breadcrumbs,
  border = "bottom",
  sticky = false,
  className,
}: Omit<AppHeaderProps, "children" | "navItems">) {
  const { navItems, mobileMenuOpen, setMobileMenuOpen } = useAppHeader();

  return (
    <header
      data-slot="app-header"
      className={cn(
        "z-40 flex h-14 w-full items-center justify-between px-4 bg-card",
        sticky && "sticky top-0",
        border === "bottom" && "border-b border-border",
        border === "full" && "border border-border rounded-lg",
        className,
      )}
    >
      {/* Left Section: Mobile Menu + Logo + Breadcrumbs */}
      <div className="flex items-center gap-3">
        {/* Mobile Menu Toggle - hidden on md+ */}
        <Button
          variant="ghost"
          size="icon"
          className="md:hidden"
          onClick={() => setMobileMenuOpen(true)}
          aria-label="Open menu"
        >
          <Menu className="h-5 w-5" />
        </Button>

        {/* Logo */}
        <div className="flex items-center gap-2">{logo ?? <DefaultLogo />}</div>

        {/* Breadcrumbs - hidden on mobile */}
        {breadcrumbs && breadcrumbs.length > 0 && (
          <>
            <Separator orientation="vertical" className="h-6 hidden sm:block" />
            <Breadcrumb items={breadcrumbs} className="hidden sm:flex" />
          </>
        )}
      </div>

      {/* Center Section: Desktop Navigation */}
      <div className="hidden md:flex flex-1 justify-center">
        <HeaderNav />
      </div>

      {/* Right Section: Actions */}
      <div className="flex items-center gap-2">
        {showOrgSwitcher && <OrganizationSwitcher />}
        {showThemeToggle && <ModeToggle />}
        {showUserMenu && <UserMenu />}
      </div>

      {/* Mobile Menu Sheet */}
      <MobileMenu />
    </header>
  );
}

// Main exported component with provider
export function AppHeader({
  children,
  navItems,
  ...props
}: AppHeaderProps) {
  return (
    <AppHeaderProvider navItems={navItems}>
      {children ?? <AppHeaderContent {...props} />}
    </AppHeaderProvider>
  );
}
```

#### Desktop Navigation (`header-nav.tsx`)

```tsx
"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";

import { cn } from "@/lib/utils";
import { buttonVariants } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";

import { useAppHeader } from "./context";

export function HeaderNav() {
  const { navItems, currentPath } = useAppHeader();

  return (
    <nav className="flex items-center gap-1">
      {navItems.map((item) => {
        const isActive = currentPath === item.href || 
          (item.href !== "/dashboard" && currentPath.startsWith(item.href));

        return (
          <Link
            key={item.href}
            href={item.href}
            className={cn(
              buttonVariants({ variant: "ghost", size: "sm" }),
              "gap-2 relative",
              isActive && "bg-accent text-accent-foreground",
              item.disabled && "pointer-events-none opacity-50",
            )}
            aria-current={isActive ? "page" : undefined}
          >
            {item.icon}
            <span>{item.label}</span>
            {item.badge != null && (
              <Badge variant="secondary" className="ml-1 h-5 px-1.5 text-xs">
                {item.badge}
              </Badge>
            )}
            {/* Active indicator underline */}
            {isActive && (
              <span className="absolute bottom-0 left-2 right-2 h-0.5 bg-primary rounded-full" />
            )}
          </Link>
        );
      })}
    </nav>
  );
}
```

#### Mobile Menu (`mobile-menu.tsx`)

```tsx
"use client";

import { LogOut, Settings, X } from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";

import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
