          </SheetDescription>
        </SheetHeader>

        {/* Navigation Links */}
        <nav className="flex flex-col p-2">
          {navItems.map((item) => {
            const isActive =
              currentPath === item.href ||
              (item.href !== "/dashboard" && currentPath.startsWith(item.href));

            return (
              <Link
                key={item.href}
                href={item.disabled ? "#" : item.href}
                onClick={handleNavClick}
                className={cn(
                  "flex items-center gap-3 rounded-md px-3 py-2.5 text-sm font-medium transition-colors",
                  isActive
                    ? "bg-accent text-accent-foreground"
                    : "text-muted-foreground hover:bg-accent/50 hover:text-foreground",
                  item.disabled && "pointer-events-none opacity-50",
                )}
                aria-current={isActive ? "page" : undefined}
              >
                {item.icon && <span className="shrink-0">{item.icon}</span>}
                {item.label}
              </Link>
            );
          })}
        </nav>

        <Separator className="my-2" />

        {/* Footer Actions */}
        <div className="flex flex-col p-2">
          <Link
            href="/settings"
            onClick={handleNavClick}
            className="flex items-center gap-3 rounded-md px-3 py-2.5 text-sm font-medium text-muted-foreground hover:bg-accent/50 hover:text-foreground transition-colors"
          >
            <Settings className="h-4 w-4" />
            Settings
          </Link>
          <button
            type="button"
            onClick={handleSignOut}
            className="flex items-center gap-3 rounded-md px-3 py-2.5 text-sm font-medium text-destructive hover:bg-destructive/10 transition-colors text-left"
          >
            <LogOut className="h-4 w-4" />
            Sign Out
          </button>
        </div>
      </SheetContent>
    </Sheet>
  );
}
