        sticky && "sticky top-0",
        border === "bottom" && "border-b border-border",
        border === "full" && "border border-border rounded-lg",
        className,
      )}
    >
      {/* Left Section: Mobile Menu + Logo + Breadcrumbs */}
      <div className="flex items-center gap-3">
        {/* Mobile Menu Toggle - hidden on md+ */}
        <Button
          variant="ghost"
          size="icon"
          className="md:hidden"
          onClick={() => setMobileMenuOpen(true)}
          aria-label="Open menu"
        >
          <Menu className="h-5 w-5" />
        </Button>

        {/* Logo */}
        <div className="flex items-center gap-2">{logo ?? <DefaultLogo />}</div>

        {/* Breadcrumbs - hidden on mobile */}
        {breadcrumbs && breadcrumbs.length > 0 && (
          <>
            <Separator orientation="vertical" className="h-6 hidden sm:block" />
            <Breadcrumb items={breadcrumbs} className="hidden sm:flex" />
          </>
        )}
      </div>

      {/* Center Section: Desktop Navigation */}
      <div className="hidden md:flex flex-1 justify-center">
        <HeaderNav />
      </div>

      {/* Right Section: Actions */}
      <div className="flex items-center gap-2">
        {showOrgSwitcher && <OrganizationSwitcher />}
        {showThemeToggle && <ModeToggle />}
        {showUserMenu && <UserMenu />}
      </div>

      {/* Mobile Menu Sheet */}
      <MobileMenu />
    </header>
  );
}

// Main exported component with provider
export function AppHeader({
  children,
  navItems,
  ...props
}: AppHeaderProps) {
  return (
    <AppHeaderProvider navItems={navItems}>
      {children ?? <AppHeaderContent {...props} />}
    </AppHeaderProvider>
